namespace Polymorfa.Sdk;

public sealed class Business : Resource
{
    internal Business(HttpTransport http) : base(http) { }
    private static string Path(string connection) => $"/messaging/{E(connection)}/business";
    private static string Profile(string connection) => Path(connection) + "/profile";
    private static string Product(string connection, string product) => Path(connection) + "/products/" + E(product);
    private static string Collection(string connection, string collection) => Path(connection) + "/collections/" + E(collection);
    public Task<ApiResponse<SuccessEnvelope<BusinessProfile>>> GetProfileAsync(string connection, RequestOptions? options = null) => Get<SuccessEnvelope<BusinessProfile>>(Profile(connection), options);
    public Task<ApiResponse<SuccessEnvelope<CommandResult<BusinessProfileStatus>>>> UpdateProfileAsync(string connection, BusinessProfileUpdateRequest body, RequestOptions? options = null) => Patch<SuccessEnvelope<CommandResult<BusinessProfileStatus>>>(Profile(connection), body, options);
    public Task<ApiResponse<SuccessEnvelope<CommandResult<BusinessCoverPhotoResult>>>> SetCoverPhotoAsync(string connection, PictureRequest body, RequestOptions? options = null) { ValidateImage(body.Url, body.Base64); return Put<SuccessEnvelope<CommandResult<BusinessCoverPhotoResult>>>(Profile(connection) + "/cover-photo", body, options); }
    public Task<ApiResponse<SuccessEnvelope<CommandResult<BusinessProfileStatus>>>> DeleteCoverPhotoAsync(string connection, string coverPhotoId, RequestOptions? options = null) => Delete<SuccessEnvelope<CommandResult<BusinessProfileStatus>>>(Profile(connection) + "/cover-photo/" + E(coverPhotoId), options);
    public Task<ApiResponse<SuccessEnvelope<BusinessCatalogPage>>> GetCatalogAsync(string connection, BusinessCatalogParameters parameters, RequestOptions? options = null) => Get<SuccessEnvelope<BusinessCatalogPage>>(Path(connection) + "/catalog", options, parameters);
    public Task<ApiResponse<SuccessEnvelope<CommandResult<BusinessActionSuccess>>>> CreateCatalogAsync(string connection, RequestOptions? options = null) => Post<SuccessEnvelope<CommandResult<BusinessActionSuccess>>>(Path(connection) + "/catalog", null, options);
    public Task<ApiResponse<SuccessEnvelope<CommandResult<BusinessActionSuccess>>>> SetCartEnabledAsync(string connection, bool enabled, RequestOptions? options = null) => Patch<SuccessEnvelope<CommandResult<BusinessActionSuccess>>>(Path(connection) + "/catalog/cart", new { enabled }, options);
    public Task<ApiResponse<SuccessEnvelope<BusinessProduct>>> GetProductAsync(string connection, string productId, string businessId, RequestOptions? options = null) => Get<SuccessEnvelope<BusinessProduct>>(Product(connection, productId), options, new { id = businessId });
    public Task<ApiResponse<SuccessEnvelope<CommandResult<BusinessProduct>>>> CreateProductAsync(string connection, BusinessProductMutationRequest body, RequestOptions? options = null) { ValidateProduct(body); return Post<SuccessEnvelope<CommandResult<BusinessProduct>>>(Path(connection) + "/products", body, options); }
    public Task<ApiResponse<SuccessEnvelope<CommandResult<BusinessProduct>>>> UpdateProductAsync(string connection, string productId, BusinessProductMutationRequest body, RequestOptions? options = null) { ValidateProduct(body); return Put<SuccessEnvelope<CommandResult<BusinessProduct>>>(Product(connection, productId), body, options); }
    public Task<ApiResponse<SuccessEnvelope<CommandResult<BusinessProductDeleteResult>>>> DeleteProductAsync(string connection, string productId, RequestOptions? options = null) => Delete<SuccessEnvelope<CommandResult<BusinessProductDeleteResult>>>(Product(connection, productId), options);
    public Task<ApiResponse<SuccessEnvelope<CommandResult<BusinessActionSuccess>>>> SetProductVisibilityAsync(string connection, string productId, bool hidden, RequestOptions? options = null) => Patch<SuccessEnvelope<CommandResult<BusinessActionSuccess>>>(Product(connection, productId) + "/visibility", new { hidden }, options);
    public Task<ApiResponse<SuccessEnvelope<CommandResult<BusinessActionSuccess>>>> AppealProductAsync(string connection, string productId, BusinessCatalogAppealRequest body, RequestOptions? options = null) => Post<SuccessEnvelope<CommandResult<BusinessActionSuccess>>>(Product(connection, productId) + "/appeal", body, options);
    public Task<ApiResponse<SuccessEnvelope<BusinessCollectionPage>>> ListCollectionsAsync(string connection, BusinessCollectionsParameters parameters, RequestOptions? options = null) => Get<SuccessEnvelope<BusinessCollectionPage>>(Path(connection) + "/collections", options, parameters);
    public Task<ApiResponse<SuccessEnvelope<BusinessCollection>>> GetCollectionAsync(string connection, string collectionId, BusinessCatalogParameters parameters, RequestOptions? options = null) => Get<SuccessEnvelope<BusinessCollection>>(Collection(connection, collectionId), options, parameters);
    public Task<ApiResponse<SuccessEnvelope<CommandResult<BusinessCollectionMutationResult>>>> CreateCollectionAsync(string connection, BusinessCollectionCreateRequest body, RequestOptions? options = null) => Post<SuccessEnvelope<CommandResult<BusinessCollectionMutationResult>>>(Path(connection) + "/collections", body, options);
    public Task<ApiResponse<SuccessEnvelope<CommandResult<BusinessCollectionMutationResult>>>> UpdateCollectionAsync(string connection, string collectionId, BusinessCollectionUpdateRequest body, RequestOptions? options = null) => Patch<SuccessEnvelope<CommandResult<BusinessCollectionMutationResult>>>(Collection(connection, collectionId), body, options);
    public Task<ApiResponse<SuccessEnvelope<CommandResult<BusinessActionSuccess>>>> DeleteCollectionAsync(string connection, string collectionId, RequestOptions? options = null) => Delete<SuccessEnvelope<CommandResult<BusinessActionSuccess>>>(Collection(connection, collectionId), options);
    public Task<ApiResponse<SuccessEnvelope<CommandResult<BusinessActionSuccess>>>> ReorderCollectionsAsync(string connection, BusinessCollectionReorderRequest body, RequestOptions? options = null) => Post<SuccessEnvelope<CommandResult<BusinessActionSuccess>>>(Path(connection) + "/collections/reorder", body, options);
    public Task<ApiResponse<SuccessEnvelope<CommandResult<BusinessActionSuccess>>>> AppealCollectionAsync(string connection, string collectionId, BusinessCatalogAppealRequest body, RequestOptions? options = null) => Post<SuccessEnvelope<CommandResult<BusinessActionSuccess>>>(Collection(connection, collectionId) + "/appeal", body, options);
    public Task<ApiResponse<SuccessEnvelope<CommandResult<BusinessOrder>>>> GetOrderAsync(string connection, string orderId, BusinessOrderLookupRequest body, RequestOptions? options = null) => Post<SuccessEnvelope<CommandResult<BusinessOrder>>>(Path(connection) + "/orders/" + E(orderId) + "/lookup", body, options);
    public Task<ApiResponse<SuccessEnvelope<BusinessMerchantCompliance>>> GetMerchantComplianceAsync(string connection, RequestOptions? options = null) => Get<SuccessEnvelope<BusinessMerchantCompliance>>(Path(connection) + "/compliance", options);
    public Task<ApiResponse<SuccessEnvelope<CommandResult<BusinessMerchantCompliance>>>> SetMerchantComplianceAsync(string connection, BusinessMerchantCompliance body, RequestOptions? options = null) => Put<SuccessEnvelope<CommandResult<BusinessMerchantCompliance>>>(Path(connection) + "/compliance", body, options);
    public Task<ApiResponse<SuccessEnvelope<BusinessLinkedAccounts>>> GetLinkedAccountsAsync(string connection, RequestOptions? options = null) => Get<SuccessEnvelope<BusinessLinkedAccounts>>(Path(connection) + "/linked-accounts", options);
    public Task<ApiResponse<SuccessEnvelope<BusinessEligibility>>> GetEligibilityAsync(string connection, RequestOptions? options = null) => Get<SuccessEnvelope<BusinessEligibility>>(Path(connection) + "/eligibility", options);
    private static void ValidateProduct(BusinessProductMutationRequest body)
    {
        foreach (var image in body.Images) if (new[] { image.Url, image.Base64, image.MediaUrl }.Count(v => v is not null) != 1) throw new PolymorfaValidationException("Product images require exactly one source.", "invalid_parameter");
    }
    private static void ValidateImage(string? url, string? base64) { if ((url is null) == (base64 is null)) throw new PolymorfaValidationException("Cover photo requires exactly one source.", "invalid_parameter"); }
}
